fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if c.is_ascii_alphabetic() {
                if c.is_ascii_lowercase() {
                    c.to_ascii_uppercase()
                } else {
                    c.to_ascii_lowercase()
                }
            } else {
                c // Keep the character unchanged if it's not an ASCII alphabetic letter
            }
        })
        .collect()
}